36	// envelope is the persisted state container.
37	//
38	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
39	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
40	// decides what a committed circuit record may look like. UnmarshalJSON first
41	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
42	// object key anywhere encoding/json would otherwise keep the last value. At
43	// the envelope's top level that comparison is case-insensitive for the five
44	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
45	// that differs only in ASCII letter case — including one JSON-escaped — names
46	// the same field and corrupts the read instead of overriding it. A spelling
47	// that Unicode case-folds onto one of those fields yet is not an ASCII case
48	// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
49	// is likewise corruption even when it is the only spelling present, since
50	// encoding/json's own tag matching would fill the field from it; a later
51	// "circuitſ": [] must never read the circuits as empty and drop them on the
52	// next commit.
53	type envelope struct {
54		Format    int               `json:"format"`
55		Circuits  []persistCircuit  `json:"circuits"`
56		Setups    []persistSetup    `json:"setups"`
57		Jobs      []persistJob      `json:"jobs"`
58		Artifacts []persistArtifact `json:"artifacts,omitempty"`
59	}
