71	func (e *envelope) UnmarshalJSON(raw []byte) error {
72		// Reject repeated keys before decoding: encoding/json silently keeps the
73		// last value of a duplicate. The walk is layered so a repeated field is
74		// attributed to the record it belongs to (a duplicate "frozen" inside
75		// circuit #3, not a generic envelope complaint).
76		if err := scanEnvelopeDuplicates(raw); err != nil {
77			return err
78		}
79		var wire envelopeWire
80		if err := json.Unmarshal(raw, &wire); err != nil {
81			var se StoreError
82			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
83				return err // an inner record decoder already named the problem
84			}
85			return corruptf("data file envelope is not valid JSON: %v", err)
86		}
87		e.Format = wire.Format
88		e.Setups = wire.Setups
89		e.Jobs = wire.Jobs
90		e.Artifacts = wire.Artifacts
91		if wire.Circuits == nil {
92			e.Circuits = nil
93		} else {
94			e.Circuits = make([]persistCircuit, len(wire.Circuits))
95		}
96		for i, craw := range wire.Circuits {
97			var record persistCircuit
98			if err := json.Unmarshal(craw, &record); err != nil {
99				var se StoreError
100				if errors.As(err, &se) {
101					// Re-tag as one corruption error carrying the record index,
102					// so the detail survives errors.As unwrapping in loadLocked.
103					return StoreError{Kind: ErrDataCorrupt.Kind,
104						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
105				}
106				return corruptf("circuit record #%d: %v", i+1, err)
107			}
108			e.Circuits[i] = record
109		}
110		return nil
111	}
