416	type persistCircuit struct {
417		Name          string             `json:"name"`
418		Version       int                `json:"version"`
419		Constraints   int                `json:"constraints"`
420		PublicInputs  int                `json:"public_inputs"`
421		PrivateInputs int                `json:"private_inputs"`
422		Frozen        bool               `json:"frozen"`
423		Description   string             `json:"description"`
424		Definition    *persistDefinition `json:"definition,omitempty"`
