981	// loadLocked reads and validates the committed file. Caller must hold the
982	// exclusive flock; the in-process mutex is taken by the public Open path.
983	func (s *Store) loadLocked() error {
984		raw, err := os.ReadFile(s.dataPath())
985		if errors.Is(err, os.ErrNotExist) {
986			s.data = envelope{Format: FormatVersion}
987			return nil
988		}
989		if err != nil {
990			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
991		}
992		if len(strings.TrimSpace(string(raw))) == 0 {
993			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
994		}
995	
996		var env envelope
997		if err := json.Unmarshal(raw, &env); err != nil {
998			// Shape failures surfaced by the persisted-definition decoders are
999			// integrity failures, not JSON syntax errors; report their detail
1000			// instead of the generic "not valid JSON" wording.
1001			var se StoreError
1002			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
1003				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
1004			}
1005			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
1006		}
1007		if env.Format == 0 {
1008			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
1009		}
1010		if env.Format != FormatVersion {
1011			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
1012				s.dataPath(), env.Format, FormatVersion)
1013		}
1014		if err := validateEnvelope(env); err != nil {
1015			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
1016		}
1017		s.data = env
1018		return nil
1019	}
1020	
1021	// commitLocked writes the pending state atomically: temp file → fsync →
1022	// rename → fsync directory. Caller must hold both the in-process mutex and
1023	// the exclusive flock; all in-memory mutations must already have happened and
1024	// been rule-checked, so a failure here occurs before any success is reported.
1025	func (s *Store) commitLocked() error {
1026		s.data.Format = FormatVersion
1027		// Stable output: records are stored sorted so files are deterministic.
1028		sortEnvelope(&s.data)
1029	
1030		payload, err := json.MarshalIndent(&s.data, "", "  ")
1031		if err != nil {
1032			return fmt.Errorf("cannot encode data: %w", err)
1033		}
1034		payload = append(payload, '\n')
1035	
1036		tmp := s.tmpPath()
1037		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
1038		if err != nil {
1039			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
1040		}
1041		if _, err := f.Write(payload); err != nil {
1042			f.Close()
1043			os.Remove(tmp)
1044			return fmt.Errorf("cannot write staged data: %w", err)
1045		}
1046		if err := f.Sync(); err != nil {
1047			f.Close()
1048			os.Remove(tmp)
1049			return fmt.Errorf("cannot flush staged data: %w", err)
1050		}
1051		if err := f.Close(); err != nil {
1052			os.Remove(tmp)
1053			return fmt.Errorf("cannot finish staged data: %w", err)
1054		}
1055		if err := os.Rename(tmp, s.dataPath()); err != nil {
1056			os.Remove(tmp)
1057			return fmt.Errorf("cannot commit data file: %w", err)
1058		}
1059		if err := syncDir(s.dir); err != nil {
1060			// The rename already happened; lack of dir fsync only weakens crash
1061			// durability, never correctness of what is visible now.
1062			return nil
1063		}
1064		return nil
1065	}
1066	
1067	// withLock runs fn under the in-process mutex and an exclusive flock, then
1068	// atomically commits when fn requests it. The on-disk state is re-read after
1069	// acquiring the lock, so concurrent commits from another process or another
1070	// handle are always observed. Operations validate before mutating; a rejected
1071	// operation (commit=false or an error) writes nothing and leaves committed
1072	// state unchanged.
1073	func (s *Store) withLock(fn func() (commit bool, err error)) error {
1074		s.mu.Lock()
1075		defer s.mu.Unlock()
1076		if s.lock == nil {
1077			return invalidf("store is closed")
1078		}
1079		if err := lockExclusive(s.lock); err != nil {
1080			return fmt.Errorf("cannot lock data directory: %w", err)
1081		}
1082		defer unlockLock(s.lock)
1083	
1084		if err := s.loadLocked(); err != nil {
1085			return err
1086		}
1087		commit, err := fn()
1088		if err != nil {
1089			return err
1090		}
1091		if !commit {
1092			return nil
1093		}
1094		return s.commitLocked()
1095	}
1096	
1097	// withLockRead runs fn under a shared flock over freshly reloaded state.
1098	func (s *Store) withLockRead(fn func() error) error {
1099		s.mu.Lock()
1100		defer s.mu.Unlock()
1101		if s.lock == nil {
1102			return invalidf("store is closed")
1103		}
1104		if err := lockShared(s.lock); err != nil {
1105			return fmt.Errorf("cannot lock data directory: %w", err)
1106		}
1107		defer unlockLock(s.lock)
1108		if err := s.loadLocked(); err != nil {
1109			return err
1110		}
1111		return fn()
1112	}
