1114	func sortEnvelope(env *envelope) {
1115		sort.Slice(env.Circuits, func(i, j int) bool {
1116			if env.Circuits[i].Name != env.Circuits[j].Name {
1117				return env.Circuits[i].Name < env.Circuits[j].Name
1118			}
1119			return env.Circuits[i].Version < env.Circuits[j].Version
1120		})
1121		sort.Slice(env.Setups, func(i, j int) bool {
1122			if env.Setups[i].Name != env.Setups[j].Name {
1123				return env.Setups[i].Name < env.Setups[j].Name
1124			}
1125			return env.Setups[i].Version < env.Setups[j].Version
1126		})
1127		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
1128		sort.Slice(env.Artifacts, func(i, j int) bool {
1129			if env.Artifacts[i].Name != env.Artifacts[j].Name {
1130				return env.Artifacts[i].Name < env.Artifacts[j].Name
1131			}
1132			return env.Artifacts[i].Version < env.Artifacts[j].Version
1133		})
1134	}
1135	
1136	// validateEnvelope re-checks every invariant on load so a tampered or
1137	// hand-edited file cannot bypass the domain rules.
1138	func validateEnvelope(env envelope) error {
1139		seenCircuit := make(map[[2]string]bool)
1140		circuitOK := make(map[[2]string]bool)
1141		for i, c := range env.Circuits {
1142			key := [2]string{c.Name, itoa(c.Version)}
1143			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
1144				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
1145			}
1146			if c.Version <= 0 {
1147				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
1148			}
1149			if seenCircuit[key] {
1150				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
1151			}
1152			seenCircuit[key] = true
1153			if c.Constraints <= 0 {
1154				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
1155			}
1156			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
1157				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
1158			}
1159			// The same representability rule the write path enforces: wire 0 plus
1160			// every declared input must fit inside the platform's int. A record
1161			// beyond that bound can never have been written by this build and
1162			// cannot be checked safely, so the directory is corrupt rather than
1163			// silently narrowed or read with a wrapped-around layout.
1164			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
1165				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
1166					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
1167			}
1168			if c.Definition != nil {
1169				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
1170					return err
1171				}
1172			}
1173			circuitOK[key] = true
1174		}
1175		seenSetup := make(map[[2]string]bool)
1176		for i, p := range env.Setups {
1177			key := [2]string{p.Name, itoa(p.Version)}
1178			if !circuitOK[key] {
1179				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
1180			}
1181			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
1182			if c == nil || !c.Frozen {
1183				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
1184			}
1185			if seenSetup[key] {
1186				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
1187			}
1188			seenSetup[key] = true
1189		}
1190		seenJob := make(map[string]bool)
1191		for i, j := range env.Jobs {
1192			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
1193				return fmt.Errorf("job #%d has an empty or blank id", i+1)
1194			}
1195			if seenJob[j.ID] {
1196				return fmt.Errorf("job %q appears more than once", j.ID)
1197			}
1198			seenJob[j.ID] = true
1199			if j.Kind != "prove" {
1200				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1201			}
1202			if j.Attempt <= 0 {
1203				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1204			}
1205			key := [2]string{j.Circuit, itoa(j.Version)}
1206			if !circuitOK[key] {
1207				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1208			}
1209			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1210			if c == nil || !c.Frozen {
1211				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1212			}
1213			if !seenSetup[key] {
1214				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1215			}
1216			// A recorded compiled-artifact binding must still resolve against the
1217			// pinned version's artifact; a dangling or mismatched binding makes
1218			// the file unreadable rather than silently dropping the binding.
1219			if j.CompiledHash != "" {
1220				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1221				if artifact == nil {
1222					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1223				}
1224				if artifact.Hash != j.CompiledHash {
1225					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1226						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1227				}
1228			}
1229		}
1230		seenArtifact := make(map[[2]string]bool)
1231		for i, a := range env.Artifacts {
1232			key := [2]string{a.Name, itoa(a.Version)}
1233			if !circuitOK[key] {
1234				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1235			}
1236			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1237			if c == nil || !c.Frozen {
1238				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1239			}
1240			if seenArtifact[key] {
1241				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1242			}
1243			seenArtifact[key] = true
1244			if c.Definition == nil {
1245				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1246			}
1247			if a.Constraints != c.Constraints {
1248				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1249					a.Name, a.Version, a.Constraints, c.Constraints)
1250			}
1251			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1252			if err != nil {
1253				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1254			}
1255			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1256				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1257			}
1258			wantHash := artifactHash(a.Name, a.Version, def)
1259			if a.Hash != wantHash {
1260				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1261					a.Name, a.Version, a.Hash, wantHash)
1262			}
1263		}
1264		return nil
1265	}
1266	
1267	// validatePersistDefinition re-validates a stored definition against its
1268	// version's declared counts: prime modulus, in-range wires and an exact
1269	// constraint count match.
1270	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1271		parsed, err := definitionFromPersist(*def, public, private)
1272		if err != nil {
1273			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1274		}
1275		if !parsed.compatibleWith(constraints, public, private) {
1276			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1277		}
1278		return nil
1279	}
1280	
1281	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1282		for i := range cs {
1283			if cs[i].Name == name && cs[i].Version == version {
1284				return &cs[i]
1285			}
1286		}
1287		return nil
1288	}
1289	
1290	func itoa(v int) string { return fmt.Sprintf("%d", v) }
1291

