func frozenSetupUncompiled(t *testing.T, s *Store, name string, v int) {
	t.Helper()
	seedDraftWithDef(t, s, name, v, 1, 1, validDef)
	if _, err := s.FreezeCircuit(name, v); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordSetup(name, v); err != nil {
		t.Fatal(err)
	}
